INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO26-041','beginner','Zasilanie','Bateria Li-ion — objawy puchnięcia','','description: Spuchnięta bateria może naciskać na touchpad i obudowę. step: Przerwij ładowanie i nie naciskaj ogniw.','','',''),
('beginner:ZERO26-042','beginner','Zasilanie','UPS — kontrola baterii i obciążenia','','description: UPS wymaga dopasowania mocy, czasu pracy i rodzaju baterii. step: Sprawdź raport self-test i datę baterii zgodnie z manualem.','','',''),
('beginner:ZERO26-043','beginner','Windows i system','Test po hibernacji Windows 26H2','','description: Wznowienie może ujawnić problemy sterownika, Bluetooth, docka lub kamery. step: Zapisz stan urządzenia, wykonaj hibernację i powtórz test.','','',''),
('beginner:ZERO26-044','beginner','Windows i system','Sterowniki OEM vs uniwersalne','','description: Sterowniki OEM mogą zawierać dostosowania do konkretnego laptopa. step: Porównaj pakiet OEM z pakietem producenta układu.','','',''),
('beginner:ZERO26-045','beginner','Dyski i dane','Kopia danych 3-2-1','','description: Kopie na tym samym dysku nie chronią przed awarią całego nośnika. step: Utwórz kopię na oddzielnym medium i sprawdź odtwarzanie.','','',''),
('beginner:ZERO26-046','beginner','Windows i system','Identyfikacja ARM64 i x64','','description: Architektura systemu ma znaczenie dla instalacji sterownika i aplikacji. step: Zapisz architekturę w Informacjach o systemie.','','',''),
('beginner:ZERO26-047','beginner','Dyski i dane','M.2 NVMe vs M.2 SATA','','description: Ten sam rozmiar dysku nie oznacza zgodnego protokołu. step: Sprawdź Key, interfejs i specyfikację laptopa.','','',''),
('beginner:ZERO26-048','beginner','Chłodzenie','Termopady i grubość','','description: Nieprawidłowa grubość termopadu może pogorszyć docisk radiatora. step: Sprawdź specyfikację OEM i nie zastępuj termopadu pastą.','','',''),
('beginner:ZERO26-049','beginner','Chłodzenie','Liquid metal w laptopie','','description: Ciekły metal przewodzi prąd i wymaga właściwego zabezpieczenia. step: Nie nakładaj go bez znajomości konstrukcji i izolacji OEM.','','',''),
('beginner:ZERO26-050','beginner','Chłodzenie','Wentylatory PWM i DC','','description: Wentylatory mogą używać różnych metod regulacji prędkości. step: Sprawdź złącze i tryb w BIOS przed zmianą krzywej.','','',''),
('beginner:ZERO26-051','beginner','Obraz i monitory','Monitor 4K/120 Hz — kabel i DSC','','description: Wysoka rozdzielczość i odświeżanie zależą od standardu portu i przewodu. step: Sprawdź specyfikację GPU, monitora i certyfikat kabla.','','',''),
('beginner:ZERO26-052','beginner','Obraz i monitory','DisplayPort DSC','','description: DSC kompresuje strumień obrazu w kompatybilnych urządzeniach. step: Przetestuj inną częstotliwość oraz kabel o właściwym standardzie.','','',''),
('beginner:ZERO26-053','beginner','Obraz i monitory','HDR i Windows 11','','description: HDR może zmieniać jasność, kolory i zachowanie monitorów. step: Zapisz tryb HDR i porównaj obraz w aplikacji testowej.','','',''),
('beginner:ZERO26-054','beginner','Porty i złącza','USB dock firmware','','description: Stacja dokująca ma własny kontroler i oprogramowanie układowe. step: Sprawdź model, wersję docka i stronę producenta.','','',''),
('beginner:ZERO26-055','beginner','Porty i złącza','PD pass-through docka','','description: Dock może dzielić moc pomiędzy laptop i urządzenia. step: Porównaj moc zasilacza, docka i zapotrzebowanie laptopa.','','',''),
('beginner:ZERO26-056','beginner','Porty i złącza','Kabel Thunderbolt aktywny vs pasywny','','description: Kable o różnych konstrukcjach mogą mieć różne możliwości i długości. step: Sprawdź certyfikację i wymagane oznaczenia.','','',''),
('beginner:ZERO26-057','beginner','Sieć i łączność','Router firmware rollback','','description: Rollback firmware bywa blokowany lub ograniczony przez producenta. step: Zapisz wersję i sprawdź oficjalną procedurę odzyskiwania.','','',''),
('beginner:ZERO26-058','beginner','Windows i bezpieczeństwo','BitLocker — klucz odzyskiwania','','description: Klucz odzyskiwania jest sekretem właściciela danych. step: Zweryfikuj identyfikator klucza i uzyskaj dostęp tylko od właściciela.','','',''),
('beginner:ZERO26-059','beginner','Windows i bezpieczeństwo','TPM 2.0 — sprawdzenie stanu','','description: TPM wspiera funkcje bezpieczeństwa, ale jego czyszczenie może utrudnić dostęp do danych. step: Odczytaj status TPM i nie czyść go bez procedury.','','',''),
('beginner:ZERO26-060','beginner','Windows i bezpieczeństwo','Secure Boot — nie wyłączaj jako obejścia','','description: Wyłączenie Secure Boot obniża ochronę wczesnego rozruchu. step: Najpierw sprawdź certyfikaty i firmware OEM.','','',''),
('beginner:ZERO26-061','beginner','Dyski i dane','Szyfrowanie SSD sprzętowe','','description: SSD może wspierać różne mechanizmy szyfrowania, zależnie od modelu. step: Sprawdź specyfikację i aktualne zalecenia producenta.','','',''),
('beginner:ZERO26-062','beginner','Dyski i dane','NVMe firmware update','','description: Aktualizacja firmware SSD może poprawiać zgodność, ale niesie ryzyko. step: Utwórz kopię i potwierdź dokładny model oraz plik.','','',''),
('beginner:ZERO26-063','beginner','Grafika i GPU','Test VRAM bez nadmiernego obciążenia','','description: Testy VRAM należy przeprowadzać przy sprawnym zasilaniu i chłodzeniu. step: Zacznij od krótkiego testu w ustawieniach fabrycznych.','','',''),
('beginner:ZERO26-064','beginner','Grafika i GPU','GPU Frame Generation a rzeczywisty FPS','','description: Generowane klatki mogą zwiększać płynność, ale nie są równoważne klatkom renderowanym. step: Porównaj opóźnienie, frametime i FPS bazowy.','','',''),
('beginner:ZERO26-065','beginner','Nowe platformy i AI','AI driver stack — GPU, NPU i runtime','','description: Aplikacje AI mogą wymagać konkretnego sterownika, runtime i modelu NPU/GPU. step: Sprawdź wymagania producenta aplikacji i sprzętu.','','',''),
('beginner:ZERO26-066','beginner','Nowe platformy i AI','Windows ML i NPU','','description: Windows ML jest jedną z warstw wykorzystywania NPU w kompatybilnych urządzeniach. step: Zweryfikuj sterownik NPU i wersję frameworka.','','',''),
('beginner:ZERO26-067','beginner','BIOS i firmware','Dziennik zmian BIOS','','description: Historia BIOS pomaga odróżnić zmianę firmware od problemu sprzętowego. step: Zapisz datę i wersję przed wykonaniem aktualizacji.','','',''),
('beginner:ZERO26-068','beginner','Pamięć i RAM','QVL pamięci i kompatybilność','','description: QVL potwierdza testy konkretnych zestawów pamięci na określonej płycie. step: Sprawdź numer SKU zestawu i listę producenta płyty.','','',''),
('beginner:ZERO26-069','beginner','Pamięć i RAM','Trening RAM po zmianie CPU','','description: Kontroler pamięci może ponownie trenować konfigurację po zmianie platformy. step: Pozwól płycie zakończyć procedurę treningu zgodnie z manualem.','','',''),
('beginner:ZERO26-070','beginner','Diagnostyka i pomiary','Raport serwisowy po naprawie','','description: Raport powinien pozwolić innemu technikowi odtworzyć testy i rezultat. step: Zapisz objaw, konfigurację, kroki, pomiary i test końcowy.','','',''),
('beginner:ZERO26-071','beginner','Zasilanie','Bezpieczna utylizacja baterii','','description: Baterie Li-ion wymagają oddzielnego, bezpiecznego kanału utylizacji. step: Zabezpiecz styki i przekaż baterię do właściwego punktu zbiórki.','','',''),
('beginner:ZERO31-001','beginner','Płyta główna / VRM','Diagnostyka sekcji zasilania CPU (VRM)','CPU VRM power-stage diagnostics','description: Analiza wejścia EPS, kontrolera PWM, faz zasilania, MOSFET-ów i cewek na podstawie schematu konkretnej płyty. step: Zapisz model i objaw. Następnie sprawdź: Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych.','descriptionEn: Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. stepEn: Record the device model and symptom. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-002','beginner','GPU / grafika','Diagnostyka braku obrazu z dedykowanej karty GPU','Dedicated GPU no-display diagnostics','description: Oddziel usterkę karty, slotu PCIe, przewodu obrazu, monitora, firmware i sterownika. step: Zapisz model i objaw. Następnie sprawdź: Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie.','descriptionEn: Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. stepEn: Record the device model and symptom. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-003','beginner','GPU / grafika','Artefakty obrazu i niestabilność pamięci VRAM','Display artifacts and VRAM instability','description: Rozpoznawanie artefaktów zależnych od temperatury, obciążenia, sterownika i połączenia wyświetlacza. step: Zapisz model i objaw. Następnie sprawdź: Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi.','descriptionEn: Identify artifacts correlated with temperature, load, driver and display connection. stepEn: Record the device model and symptom. Identify artifacts correlated with temperature, load, driver and display connection. Use the OEM service documentation and change only one variable at a time.','',''),
('beginner:ZERO31-004','beginner','BIOS / firmware','Odtwarzanie BIOS z funkcji Flashback','BIOS recovery using Flashback','description: Przygotowanie zgodnego obrazu firmware, nośnika USB, nazwy pliku i sekwencji odzyskiwania według OEM. step: Zapisz model i objaw. Następnie sprawdź: Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję.','descriptionEn: Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. stepEn: Record the device model and symptom. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Use the OEM service documentation and change only one variable at a time.','','');
